import React, { useState, useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import "./result.css";

function ResultPage() {
  const location = useLocation();
  const navigate = useNavigate();
  const { symptoms = [], predictions = [], symptom_details = [] } = location.state || {};

  // 🌐 language state
  const [language, setLanguage] = useState(() => localStorage.getItem("lang") || "english");
  const [showPopup, setShowPopup] = useState(!localStorage.getItem("lang"));

  const handleSelect = (lang) => {
    setLanguage(lang);
    localStorage.setItem("lang", lang);
    setShowPopup(false);
  };

  return (
    <div className="result-container">
      {/* 🌐 Language selector popup */}
      {showPopup && (
        <div className="language-popup">
          <div className="popup-box">
            <h3>Choose your language</h3>
            <p>Would you like to view your results in English or Kriol?</p>
            <button onClick={() => handleSelect("english")}>English</button>
            <button onClick={() => handleSelect("kriol")}>Kriol</button>
          </div>
        </div>
      )}

      {/* small inline selector */}
      <div className="lang-toggle">
        <label>View in: </label>
        <select value={language} onChange={(e) => handleSelect(e.target.value)}>
          <option value="english">English</option>
          <option value="kriol">Kriol</option>
        </select>
      </div>

      <h2>🩺 Health Summary ({language === "kriol" ? "Kriol" : "English"})</h2>
      <p>Here’s what we found based on your symptoms.</p>

      <div className="result-section">
        <h3>Detected Symptoms:</h3>
        {symptom_details.map((item, i) => (
          <div key={i} className="symptom-card">
            <h4>• {item.symptom}</h4>
            <p>
              <b>Description:</b>{" "}
              {language === "kriol" ? item.description_kriol || item.description : item.description}
            </p>
            <p>
              <b>Common causes:</b>{" "}
              {language === "kriol" ? item.common_causes_kriol || item.common_causes : item.common_causes}
            </p>
            <p>
              <b>Advice:</b>{" "}
              {language === "kriol" ? item.advice_kriol || item.advice : item.advice}
            </p>
          </div>
        ))}
      </div>

      <div className="result-section">
        <h3>Possible Conditions:</h3>
        <ul>
          {predictions.map((p, i) => (
            <li key={i}>
              <b>{p.disease}</b> — confidence: {Math.round(p.score * 100)}%
            </li>
          ))}
        </ul>
      </div>

      <button onClick={() => navigate("/")} className="btn-back">
        Back to Chat
      </button>
    </div>
  );
}

export default ResultPage;
